// Doodle
// let Sandor, 2014

let sX = 1;
let sY = 1;
let x = 250;
let y = 250;

function setup() {
  createCanvas(500, 500);
  background(255);
  fill(255, 20);
  stroke(0, 20);
}

function draw() {
  if (frameCount % 500 == 0) {
    rect(-1, -1, width + 1, height + 1);
  }
  for (let a = 0; a < TWO_PI; a += 0.02) {
    push();
    translate(x, y);
    rotate(a);
    let r = 500 * pow(noise(cos(a), sin(a), frameCount * 0.01), 4);
    translate(r, r);
    line(0, 0, 0, 0);
    pop();
  }
  x += sX;
  y += sY;
  if (x < 0 || x > width || random(1) < 0.003) {
    sX = -sX;
  }
  if (y < 0 || y > height || random(1) < 0.003) {
    sY = -sY;
  }
}
